<?php
/** Public text contract in disposable WordPress; no mail or participant creation. */
define('DOING_CRON',true);require __DIR__.'/m0/bootstrap.php';require_once EIPSI_FORMS_PLUGIN_DIR.'includes/study-engine/builder.php';require_once EIPSI_FORMS_PLUGIN_DIR.'includes/study-engine/longitudinal/CapabilityLanding.php';
use EIPSI\StudyEngine\Runtime\PublicMessages as M;
use EIPSI\StudyEngine\Builder\Draft as D;
use EIPSI\StudyEngine\Longitudinal as L;
$savedLanguage=get_option('eipsi_forms_language',null);$tests=0;$failures=0;$prior=get_option('eipsi_study_public_fallback_messages',null);$owned=array();
function pm_assert($v,$message='Assertion failed'){if(!$v)throw new RuntimeException($message);}
function pm_test($name,$fn){global $tests,$failures;$tests++;try{$fn();echo "PASS $name\n";}catch(Throwable $e){$failures++;echo "FAIL $name: ".$e->getMessage().' '.$e->getLine()."\n";}}
function pm_definition(){return L\Configuration::apply(D::create('MSG_STUDY','MSG_PUBLIC',1),array('initial_screen'=>L\InitialScreen::defaults()));}
function pm_frame($d,$kind='WAIT'){return array('definition'=>$d,'study'=>array('public_id'=>'MSG_PUBLIC','allow_restart'=>1),'csrf'=>'TEST','longitudinal'=>true,'access'=>array('execution_id'=>'MSG_EXEC'),'view'=>array('revision'=>0,'next_action'=>array('kind'=>$kind,'payload'=>array('until'=>'2026-10-18T08:00:00Z')),'snapshot'=>array('clock'=>'2026-10-18T07:00:00Z','execution'=>array('timezone'=>'UTC'))));}
try{
 pm_test('Study date format is shared across timezone presentation and preserves ISO inputs',function(){
 $date='2028-02-29T23:30:00Z';foreach(array('YYYY-MM-DD'=>'2028-02-29 20:30 -03','DD/MM/YYYY'=>'29/02/2028 20:30 -03','MM/DD/YYYY'=>'02/29/2028 20:30 -03') as $format=>$expected){$d=pm_definition();$d['protocol_metadata']['date_format']=$format;pm_assert(EIPSI\StudyEngine\Runtime\DateFormat::read($d)===$format);pm_assert(L\EmailTemplate::local($date,'America/Argentina/Buenos_Aires',$format)===$expected);pm_assert(L\EmailTemplate::local(null,'UTC',$format)==='');}pm_assert($date==='2028-02-29T23:30:00Z');try{EIPSI\StudyEngine\Runtime\DateFormat::read(array('protocol_metadata'=>array('date_format'=>'INVALID')));throw new RuntimeException('Accepted invalid format');}catch(DomainException $e){pm_assert($e->getMessage()==='INVALID_STUDY_DATE_FORMAT');}
 });
 pm_test('Message catalog has unique keys and complete default values',function(){pm_assert(count(M::catalog())===count(M::defaults()));foreach(M::catalog() as $r)pm_assert($r['key']!==''&&$r['label']!==''&&$r['group']!==''&&is_string($r['default']));});
 pm_test('Message validation rejects unknown keys nontext malformed UTF8 and overlong values',function(){foreach(array(array('bad'=>'x'),array('wait_title'=>array()),array('wait_title'=>"\xff"),array('wait_title'=>str_repeat('a',16001))) as $bad){try{M::validate($bad);throw new RuntimeException('Accepted invalid message');}catch(DomainException $expected){}}});
 pm_test('Individual texts preserve blank values literal variables and isolation',function(){$a=pm_definition();$a['protocol_metadata']['public_messages']=array('wait_body'=>'','email_not_found'=>'Falta [PERTENENCIA]','change_body'=>'$1 <ejemplo> & prueba');$before=json_encode($a);pm_assert(M::text($a,'wait_body')==='');pm_assert(M::text($a,'email_not_found',array('PERTENENCIA'=>'Mi casilla'))==='Falta Mi casilla');pm_assert(M::text(pm_definition(),'wait_body')!=='');pm_assert(json_encode($a)===$before);});
 pm_test('Unidentified fallback uses global language while known Study keeps creation language',function(){delete_option('eipsi_study_public_fallback_messages');$known=array('protocol_metadata'=>array('content_language'=>'en','public_messages'=>array('operation_failed'=>'Authored error')));foreach(array('en','es') as $language){update_option('eipsi_forms_language',$language,false);pm_assert(M::text(array(),'operation_failed')===EIPSI\I18n\ContentDefaults::get('public_messages',$language)['operation_failed']);pm_assert(M::text($known,'operation_failed')==='Authored error');}delete_option('eipsi_forms_language');});
 pm_test('Global fallback never overrides an identified study',function(){update_option('eipsi_study_public_fallback_messages',array('access_denied'=>'Respaldo propio'));pm_assert(M::text(array(),'access_denied')==='Respaldo propio');pm_assert(M::text(pm_definition(),'access_denied')===M::defaults()['access_denied']);});
 pm_test('Removed access confirmation and return-link controls are absent from active configuration',function(){foreach(M::catalog() as $field)if(in_array($field['key'],array('access_title','access_body','access_button','return_initial'),true))pm_assert(!empty($field['retired']));pm_assert(!in_array('return_initial',array_column(M::fallbackFields(),'key'),true));});
 pm_test('Review and correction labels and pending email are editable and escaped',function(){$d=pm_definition();$d['protocol_metadata']['public_messages']=array('review_title'=>'Revisá propio','review_body'=>'Descripción propia','review_label'=>'Tu dirección','review_button'=>'Confirmar propio','review_link_button'=>'Enviar propio','review_pending'=>'Pendiente [EMAIL]');$f=pm_frame($d);$f['email_confirmation']=array('email'=>'x@example.invalid','pending'=>true,'requires_link'=>false);$html=(new L\EmailTemplate())->screen($f);foreach(array('Revisá propio','Descripción propia','Tu dirección','Confirmar propio','Pendiente x@example.invalid','data-study-messages') as $text)pm_assert(strpos($html,$text)!==false,$text);pm_assert(strpos($html,'value="" maxlength="254"')!==false);$f['email_confirmation']['requires_link']=true;pm_assert(strpos((new L\EmailTemplate())->screen($f),'Enviar propio')!==false);});
 pm_test('WAIT completion termination and finalized pages use configured texts',function(){$d=pm_definition();$d['protocol_metadata']['public_messages']=array('wait_title'=>'Espera propia','wait_body'=>'Descripción propia','next_time'=>'Siguiente momento:','finished_title'=>'Fin propio','finished_body'=>'Fin cuerpo','terminated_title'=>'Terminado propio','terminated_body'=>'Terminado cuerpo','withdrawn_title'=>'Retirado propio','withdrawn_body'=>'Retirado cuerpo','finalized_title'=>'Finalizado propio','finalized_body'=>'Finalizado cuerpo','unavailable_title'=>'Error propio','operation_failed'=>'Intento propio');$renderer=new EIPSI\StudyEngine\Content\AssessmentRenderer();foreach(array('WAIT'=>'Espera propia','FINISHED'=>'Fin propio','TERMINATED'=>'Terminado propio','WITHDRAWN'=>'Retirado propio','OPERATIONAL_ERROR'=>'Error propio') as $state=>$text)pm_assert(strpos($renderer->render(pm_frame($d,$state)),$text)!==false,$state);pm_assert(strpos($renderer->render(pm_frame($d)),'Siguiente momento:')!==false);$html=EIPSI\StudyEngine\Runtime\PublicStudyRepository::finalizedHtml($d);pm_assert(strpos($html,'data-state="FINALIZED"')!==false&&strpos($html,'Finalizado cuerpo')!==false);$f=pm_frame($d);$f['notice_keys']=array('email_verified','assessment_expired','email_verified');$d['protocol_metadata']['longitudinal']['show_next_time']=true;$f['definition']=$d;$portal=(new L\EmailTemplate())->screen($f);pm_assert(strpos($portal,'eipsi-initial')!==false&&strpos($portal,'name="email"')!==false);foreach(array('email_verified','assessment_expired','wait_title','next_time') as $key)pm_assert(substr_count($portal,'data-notice="'.$key.'"')===1,$key);pm_assert(strpos($portal,'data-notice="email_verified"')<strpos($portal,'id="study-email"'));pm_assert(strpos($portal,'Descripción propia')===false);});
 pm_test('Abandonment auxiliary texts and browser payload preserve special characters',function(){$d=pm_definition();$d['protocol_metadata']['longitudinal']['initial_screen']['withdrawal']['typed_confirmation']=true;$d['protocol_metadata']['public_messages']=array('withdrawal_input_label'=>'Confirmación propia','withdrawal_no_script'=>'Activá propio','change_body'=>'$1 <texto> & "comillas"');$f=pm_frame($d);$f['entry']=true;$f['message']=null;$html=(new L\EmailTemplate())->screen($f);pm_assert(strpos($html,'aria-label="Confirmación propia"')!==false&&strpos($html,'Activá propio')!==false);preg_match('/data-study-messages="([^"]*)"/',$html,$m);$payload=json_decode(html_entity_decode($m[1],ENT_QUOTES|ENT_HTML5,'UTF-8'),true);pm_assert($payload['change_body']==='$1 <texto> & "comillas"');pm_assert(strpos($html,'<texto>')===false);});
 pm_test('Draft saves public messages without applying edits to an earlier copy',function()use(&$owned,&$svc){wp_set_current_user(1);$svc=new EIPSI\StudyEngine\Builder\Service(new EIPSI\StudyEngine\Persistence\Database($GLOBALS['wpdb']));$r=$svc->create(array('name'=>'Message contract'),'PUBLIC_MESSAGES_'.bin2hex(random_bytes(8)));$owned[]=$r['study_id'];$d=$r['definition'];$d['protocol_metadata']['public_messages']=array('wait_title'=>'Primera copia');$saved=$svc->save($r['id'],$r['revision'],'MESSAGE_SAVE',$d);pm_assert($saved['definition']['protocol_metadata']['public_messages']['wait_title']==='Primera copia');$next=$saved['definition'];$next['protocol_metadata']['public_messages']['wait_title']='Segunda copia';$svc->save($r['id'],$saved['revision'],'MESSAGE_SAVE_2',$next);pm_assert($saved['definition']['protocol_metadata']['public_messages']['wait_title']==='Primera copia');});
}finally{if($savedLanguage===null)delete_option('eipsi_forms_language');else update_option('eipsi_forms_language',$savedLanguage,false);if($prior===null)delete_option('eipsi_study_public_fallback_messages');else update_option('eipsi_study_public_fallback_messages',$prior);foreach($owned as $id)try{$svc->deleteStudy($id,'ELIMINAR '.$id);}catch(Throwable $e){$failures++;echo 'FAIL cleanup '.$e->getMessage()."\n";}}
echo "$tests tests, $failures failures\n";exit($failures?1:0);
